import javax.tools.*;import com.sun.source.util.*;import java.util.*;
public class ParseJava { public static void main(String[] args) throws Exception { var compiler=ToolProvider.getSystemJavaCompiler(); var d=new DiagnosticCollector<JavaFileObject>(); try(var fm=compiler.getStandardFileManager(d,null,null)){var t=(JavacTask)compiler.getTask(null,fm,d,List.of("-proc:none"),null,fm.getJavaFileObjectsFromStrings(Arrays.asList(args)));t.parse();} for(var x:d.getDiagnostics()) {System.err.println(x);if(x.getKind()==Diagnostic.Kind.ERROR)System.exit(1);}System.out.println("PASS Java syntax parse "+args.length+" files (not Android type compilation)");}}
